// V14 security layer: lightweight abuse protection. This is intentionally in-memory; use a
// shared rate limiter (Redis/etc.) when deploying multiple backend instances.
const rateBuckets=new Map();
function rateLimit({windowMs=60000,max=120,keyPrefix="api"}={}){return (req,res,next)=>{const key=`${keyPrefix}:${req.ip||req.socket.remoteAddress||"unknown"}`;const now=Date.now();let b=rateBuckets.get(key);if(!b||now-b.start>=windowMs)b={start:now,count:0};b.count++;rateBuckets.set(key,b);if(b.count>max){res.set("Retry-After",String(Math.ceil((b.start+windowMs-now)/1000)));return res.status(429).json({error:"Too many requests. Please try again shortly."});}next();};}
app.use('/api/',rateLimit({windowMs:60000,max:180,keyPrefix:'api'}));
const loginLimit=rateLimit({windowMs:15*60000,max:12,keyPrefix:'login'});
const donationLimit=rateLimit({windowMs:10*60000,max:10,keyPrefix:'donation'});
const txidRegex=/^[a-fA-F0-9]{64}$/;
