app.get('/uploads/:name',(req,res)=>{const f=db.prepare("SELECT cf.*,c.status FROM campaign_files cf JOIN campaigns c ON c.id=cf.campaign_id WHERE cf.stored_name=? AND cf.kind='photo' AND c.status='approved' AND c.verified=1").get(req.params.name);if(!f)return res.status(404).end();res.sendFile(path.join(uploadDir,f.stored_name));});
const storage=multer.diskStorage({destination:uploadDir,filename:(_,f,cb)=>cb(null,`${Date.now()}-${Math.random().toString(36).slice(2)}-${f.originalname.replace(/[^a-zA-Z0-9._-]/g,"_")}`)});
const upload=multer({storage,limits:{fileSize:Number(process.env.UPLOAD_MAX_MB||10)*1024*1024},fileFilter:(_,f,cb)=>cb(null,new Set(["image/jpeg","image/png","image/webp","application/pdf","video/webm","video/mp4"]).has(f.mimetype))});
function notify(userId,type,title,message,data={}){db.prepare("INSERT INTO notifications(user_id,type,title,message,data_json) VALUES(?,?,?,?,?)").run(userId,type,title,message,JSON.stringify(data));}
function pub(c){const photo=db.prepare("SELECT stored_name FROM campaign_files WHERE campaign_id=? AND kind='photo' ORDER BY id ASC LIMIT 1").get(c.id);const disabled=!!c.withdrawal_disabled_at;const hidden=!!c.public_hidden_at;const withdrawalAge=disabled?Date.now()-new Date(c.withdrawal_disabled_at).getTime():Infinity;const publicWithdrawalStatus=disabled&&withdrawalAge>=0&&withdrawalAge<24*3600000;return{id:c.id,title:c.title,patientName:c.patient_name,story:c.story,goalUsdt:c.goal_usdt,raisedUsdt:c.raised_usdt,balanceUsdt:campaignBalance(c.id),status:c.status,verified:!!c.verified,createdAt:c.created_at,relationship:c.relationship,victimIsMinor:!!c.victim_is_minor,photoUrl:photo?`/uploads/${encodeURIComponent(photo.stored_name)}`:null,withdrawalDisabled:disabled,publicWithdrawalStatus,publicHidden:hidden,publicMessage:publicWithdrawalStatus?'Withdrawal initiated — donations are temporarily closed for this campaign.':''};}
function campaignEvidence(c){const files=db.prepare("SELECT id,kind,file_name,stored_name,created_at FROM campaign_files WHERE campaign_id=? ORDER BY id ASC").all(c.id).map(f=>({...f,url:`/uploads/${encodeURIComponent(f.stored_name)}`}));return{id:c.id,title:c.title,patientName:c.patient_name,story:c.story,goalUsdt:c.goal_usdt,creatorAge:c.creator_age,victimIsMinor:!!c.victim_is_minor,relationship:c.relationship,hospitalName:c.hospital_name,hospitalAddress:c.hospital_address,hospitalPhone:c.hospital_phone,doctorName:c.doctor_name,diagnosis:c.diagnosis,treatmentType:c.treatment_type,estimatedCostUsdt:c.estimated_cost_usdt,creatorLivenessStatus:c.creator_liveness_status,verificationStatus:c.verification_status,verificationNotes:c.verification_notes,verifiedAt:c.verified_at,creator:db.prepare("SELECT id,name,email,country,date_of_birth,profile_photo,kyc_status,liveness_status,liveness_file,account_status FROM users WHERE id=?").get(c.user_id),files};}
function donorLevel(id){const row=db.prepare("SELECT COUNT(*) n FROM donations WHERE donor_user_id=? AND status='confirmed' AND amount_usdt>=10").get(id); const n=row.n; if(n>=20)return"Diamond B"; if(n>=19)return"Diamond A"; if(n>=11)return"Gold"; return"Silver";}
function donorStats(id){const total=db.prepare("SELECT COALESCE(SUM(amount_usdt),0) total FROM donations WHERE donor_user_id=? AND status='confirmed'").get(id).total; const qualified=db.prepare("SELECT COUNT(*) n FROM donations WHERE donor_user_id=? AND status='confirmed' AND amount_usdt>=10").get(id).n; return{totalUsdt:total,qualifiedDonations:qualified,level:donorLevel(id)};}
function campaignBalance(id){const raised=Number(db.prepare("SELECT COALESCE(raised_usdt,0) n FROM campaigns WHERE id=?").get(id)?.n||0);const withdrawn=Number(db.prepare("SELECT COALESCE(SUM(amount_usdt),0) n FROM withdrawals WHERE campaign_id=? AND status NOT IN ('rejected')").get(id)?.n||0);return Math.max(0,raised-withdrawn);}
function workdaysFrom(date,n){let d=new Date(date);while(n>0){d.setDate(d.getDate()+1);const day=d.getDay();if(day!==0&&day!==6)n--;}return d.toISOString();}
function cleanTestimony(s){return String(s||'').trim().replace(/[^A-Za-z0-9 .,!?'-]/g,'').slice(0,700);}
function containsPrivateData(s){const x=String(s||'');return /https?:\/\/|www\.|@[A-Za-z0-9.-]+\.[A-Za-z]{2,}|\b(?:\+?\d[\d ()-]{7,}|\d{10,16})\b|T[A-Za-z0-9]{20,60}/i.test(x);}

