const COUNTRY_NAMES={NG:'Nigeria',GH:'Ghana',KE:'Kenya',ZA:'South Africa',US:'United States',GB:'United Kingdom',CA:'Canada',DE:'Germany',FR:'France',IN:'India',AE:'United Arab Emirates',SA:'Saudi Arabia',EG:'Egypt',TZ:'Tanzania',UG:'Uganda',RW:'Rwanda',ET:'Ethiopia',SN:'Senegal',CI:"Côte d’Ivoire",CM:'Cameroon',SL:'Sierra Leone',LR:'Liberia',BJ:'Benin',TG:'Togo',BF:'Burkina Faso',NE:'Niger',ML:'Mali',SD:'Sudan',AU:'Australia',BR:'Brazil',MX:'Mexico',ES:'Spain',IT:'Italy',NL:'Netherlands',SE:'Sweden',NO:'Norway',JP:'Japan',CN:'China',PK:'Pakistan',BD:'Bangladesh',ID:'Indonesia',MY:'Malaysia',PH:'Philippines'};
function normalizeCountryCode(v){const x=String(v||'').trim().toUpperCase();if(/^[A-Z]{2}$/.test(x))return x;const aliases={NIGERIA:'NG',GHANA:'GH',KENYA:'KE','SOUTH AFRICA':'ZA','UNITED STATES':'US','UNITED STATES OF AMERICA':'US','USA':'US','UNITED KINGDOM':'GB','UK':'GB',CANADA:'CA',GERMANY:'DE',FRANCE:'FR',INDIA:'IN','UNITED ARAB EMIRATES':'AE','UAE':'AE','SAUDI ARABIA':'SA',EGYPT:'EG',TANZANIA:'TZ',UGANDA:'UG',RWANDA:'RW',ETHIOPIA:'ET',SENEGAL:'SN',CAMEROON:'CM','SIERRA LEONE':'SL',LIBERIA:'LR',BENIN:'BJ','TOGO':'TG','BURKINA FASO':'BF','NIGER':'NE','MALI':'ML','SUDAN':'SD',AUSTRALIA:'AU',BRAZIL:'BR',MEXICO:'MX',SPAIN:'ES',ITALY:'IT',NETHERLANDS:'NL',SWEDEN:'SE',NORWAY:'NO',JAPAN:'JP',CHINA:'CN',PAKISTAN:'PK',BANGLADESH:'BD',INDONESIA:'ID',MALAYSIA:'MY',PHILIPPINES:'PH'};return aliases[x]||'XX';}
function countryName(code){return COUNTRY_NAMES[code]||((code==='XX')?'Unknown':code);}
function countryFlag(code){const c=normalizeCountryCode(code);return c==='XX'?'🌍':String.fromCodePoint(...[...c].map(ch=>127397+ch.charCodeAt(0)));}
function requestCountry(req){return normalizeCountryCode(req.headers['cf-ipcountry']||req.headers['x-country-code']||req.headers['x-vercel-ip-country']||req.headers['x-appengine-country']||'XX');}

function platformTrust(){const stats=db.prepare("SELECT COUNT(*) n, COALESCE(AVG(rating),0) avg FROM platform_ratings").get();const counts=db.prepare("SELECT rating,COUNT(*) n FROM platform_ratings GROUP BY rating").all();return {average:Number(stats.avg||0),count:stats.n,breakdown:Object.fromEntries(counts.map(x=>[x.rating,x.n]))};}
app.post('/api/analytics/visit',(req,res)=>{try{
 const code=requestCountry(req), page=String(req.body.page||'/').slice(0,120);
 let role='anonymous',gender='',accountCountry='';
 const h=String(req.headers.authorization||'');
 if(h.startsWith('Bearer ')){try{const u=jwt.verify(h.slice(7),process.env.JWT_SECRET);if(u){role=u.role||'anonymous';gender=String(u.gender||'');accountCountry=normalizeCountryCode(u.country||'')}}catch{}}
 const finalCode=accountCountry!=='XX'?accountCountry:code;
 db.prepare("INSERT INTO analytics_visits(visit_date,country_code,country_name,page,role,gender) VALUES(date('now'),?,?,?,?,?)").run(finalCode,countryName(finalCode),page,role,gender);
 res.json({ok:true});
}catch(e){res.status(200).json({ok:false})}});
