 const countries=db.prepare(`SELECT country_code code,MAX(country_name) name,COUNT(*) visits FROM analytics_visits WHERE visit_date>=date('now',?) GROUP BY country_code ORDER BY visits DESC LIMIT 20`).all(`-${days-1} days`);
