app.post("/api/auth/login",loginLimit,async(req,res)=>{try{const email=String(req.body.email||"").trim().toLowerCase(),password=String(req.body.password||"");const u=db.prepare("SELECT * FROM users WHERE email=?").get(email);if(!u||!(await bcrypt.compare(password,u.password_hash)))return res.status(401).json({error:"Invalid email or password"});if(u.role!=="admin"&&!u.email_verified)return res.status(403).json({error:"Please confirm your email before logging in"});let trusted=trustedDeviceFor(req,u.id);if(!trusted){const deviceCount=Number(db.prepare("SELECT COUNT(*) n FROM trusted_devices WHERE user_id=?").get(u.id)?.n||0);if(deviceCount===0){const device=issueTrustedDevice(u.id);setDeviceCookie(res,device.raw);trusted=device;}else{db.prepare("DELETE FROM login_challenges WHERE user_id=? OR expires_at<=CURRENT_TIMESTAMP").run(u.id);const raw=crypto.randomBytes(32).toString('hex'),hash=crypto.createHash('sha256').update(raw).digest('hex');db.prepare("INSERT INTO login_challenges(token_hash,user_id,expires_at) VALUES(?,?,datetime('now','+30 minutes'))").run(hash,u.id);const sent=await sendNewDeviceLoginEmail(u.name,u.email,raw);return res.status(202).json({requiresDeviceConfirmation:true,emailSent:sent,message:sent?'For your security, this phone or computer is not trusted yet. We sent a confirmation link to your CareFund email. Open it on this device to complete login.':'For your security, this phone or computer is not trusted yet. The confirmation link was logged by the server because email service is not configured.'});}}const safe={id:u.id,title:u.title||'Mr.',name:u.name,email:u.email,role:u.role,country:u.country,profilePhoto:u.profile_photo,kycStatus:u.kyc_status,livenessStatus:u.liveness_status,passwordChangedAt:u.password_changed_at};res.json({user:safe,token:signUser(safe,trusted.hash)});}catch(e){console.error(e);res.status(500).json({error:"Could not log in"})}});
