app.post("/api/campaigns",authRequired,roleRequired("fundraiser"),(req,res)=>{const existing=db.prepare("SELECT id,status FROM campaigns WHERE user_id=? ORDER BY id DESC LIMIT 1").get(req.user.id);if(existing){const completed=db.prepare("SELECT id FROM withdrawals WHERE campaign_id=? AND requested_by=? AND status='received' LIMIT 1").get(existing.id,req.user.id);if(!completed)return res.status(400).json({error:'You can only have one campaign at a time. Complete the current campaign and withdrawal cycle before creating another.'});}const u0=db.prepare("SELECT account_status FROM users WHERE id=?").get(req.user.id);if(u0?.account_status==='suspended')return res.status(403).json({error:'Your account is restricted. Contact CareFund support.'});const last=db.prepare("SELECT next_campaign_at FROM campaigns WHERE user_id=? AND next_campaign_at IS NOT NULL ORDER BY id DESC LIMIT 1").get(req.user.id);if(last?.next_campaign_at&&new Date(last.next_campaign_at)>new Date())return res.status(400).json({error:`You can create another campaign after ${last.next_campaign_at}.`});const{title,patientName,story,goalUsdt,creatorAge,victimIsMinor,relationship,hospitalName,hospitalAddress,hospitalPhone,doctorName,diagnosis,treatmentType,estimatedCostUsdt}=req.body;const age=Number(creatorAge),goal=Number(goalUsdt),estimated=Number(estimatedCostUsdt||0);if(!title||!patientName||!story||!Number.isFinite(goal)||goal<=0||!Number.isInteger(age))return res.status(400).json({error:"Complete campaign details and creator age are required"});if(age<18)return res.status(403).json({error:"Campaign creators must be 18 or older"});const u=db.prepare("SELECT liveness_status FROM users WHERE id=?").get(req.user.id);if(u.liveness_status!=='verified')return res.status(403).json({error:"Complete the liveness camera check before creating a campaign"});if(Number(victimIsMinor)===1&&!String(relationship||"").trim())return res.status(400).json({error:"Relationship to the minor is required"});if(!String(hospitalName||"").trim()||!String(hospitalAddress||"").trim())return res.status(400).json({error:"Hospital name and address are required for medical campaign verification"});if(!String(diagnosis||"").trim()||!String(treatmentType||"").trim())return res.status(400).json({error:"Diagnosis and treatment information are required"});const r=db.prepare("INSERT INTO campaigns(user_id,title,patient_name,story,goal_usdt,creator_age,victim_is_minor,relationship,creator_liveness_status,hospital_name,hospital_address,hospital_phone,doctor_name,diagnosis,treatment_type,estimated_cost_usdt,verification_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(req.user.id,String(title).trim(),String(patientName).trim(),String(story).trim(),goal,age,Number(victimIsMinor)?1:0,String(relationship||"").trim(),"verified",String(hospitalName).trim(),String(hospitalAddress).trim(),String(hospitalPhone||"").trim(),String(doctorName||"").trim(),String(diagnosis).trim(),String(treatmentType).trim(),Number.isFinite(estimated)?estimated:0,'pending');res.status(201).json({campaign:pub(db.prepare("SELECT * FROM campaigns WHERE id=?").get(r.lastInsertRowid))});});
