app.post("/api/donations/verify",donationLimit,authRequired,roleRequired("donor"),async(req,res)=>{try{const campaignId=Number(req.body.campaignId),txHash=normalizeTxid(req.body.txHash),message=String(req.body.message||'').trim();if(!campaignId||!txHash)return res.status(400).json({error:"campaignId and TXID are required"});if(!txidRegex.test(txHash))return res.status(400).json({error:"Enter a valid 64-character blockchain TXID"});const c=db.prepare("SELECT * FROM campaigns WHERE id=? AND status='approved'").get(campaignId);if(!c)return res.status(404).json({error:"Approved campaign not found"});if(c.withdrawal_disabled_at)return res.status(400).json({error:'Donations are closed because a withdrawal has been initiated for this campaign.'});if(c.raised_usdt>=c.goal_usdt)return res.status(400).json({error:"This campaign has reached its target and is closed to donations"});if(db.prepare("SELECT id FROM donations WHERE tx_hash=?").get(txHash))return res.status(409).json({error:"This transaction has already been recorded"});const t=await findUsdtTransfer(txHash);if(!t.found)return res.status(400).json({error:"Confirmed USDT TRC20 transfer not found for the CareFund wallet"});if(t.recipient!==WALLET||t.token!==USDT)return res.status(400).json({error:"Transaction does not match the CareFund USDT TRC20 wallet"});const remaining=c.goal_usdt-c.raised_usdt;if(t.amount>remaining+0.000001)return res.status(400).json({error:`Donation exceeds the remaining campaign target of ${remaining.toFixed(6)} USDT`});db.prepare("INSERT INTO donations(campaign_id,donor_user_id,amount_usdt,tx_hash,sender_address,recipient_address,status,confirmations,block_timestamp,donor_message) VALUES(?,?,?,?,?,?,?,?,?,?)").run(campaignId,req.user.id,t.amount,t.txHash,t.sender,t.recipient,'pending',t.confirmations,t.blockTimestamp,message);const admin=db.prepare("SELECT id FROM users WHERE role='admin' LIMIT 1").get();if(admin)notify(admin.id,'donation_verification','New donation payment awaiting verification',`${req.user.name||'A donor'} submitted ${t.amount} USDT to ${c.title}.`,{campaignId,donationTx:t.txHash});res.status(201).json({ok:true,donation:{campaignId,amountUsdt:t.amount,txHash:t.txHash,status:'pending',message:'Payment claim submitted. It will appear to the beneficiary only after admin verification.'}});}catch(e){console.error(e);res.status(502).json({error:'Blockchain verification service unavailable'});}});
