app.post("/api/withdrawals",authRequired,roleRequired("fundraiser"),upload.single("id"),(req,res)=>{const c=db.prepare("SELECT * FROM campaigns WHERE id=? AND user_id=?").get(req.body.campaignId,req.user.id);if(!c)return res.status(404).json({error:'Campaign not found'});if(c.status!=='approved'||!c.verified)return res.status(400).json({error:'Only a verified, approved campaign can request a withdrawal.'});if(c.withdrawal_disabled_at)return res.status(400).json({error:'A withdrawal has already been initiated for this campaign.'});const raised=Number(c.raised_usdt),pct=raised/c.goal_usdt*100;if(pct<60)return res.status(400).json({error:`Withdrawal becomes available at 60%. Current progress is ${pct.toFixed(1)}%.`});const balance=campaignBalance(c.id);const amount=Number(req.body.amount);if(!Number.isFinite(amount)||amount<=0||amount>balance+0.000001)return res.status(400).json({error:`Invalid withdrawal amount. Available campaign balance is ${balance.toFixed(2)} USDT.`});const fee=amount*.10,net=amount-fee,method=req.body.method==='bank'?'bank':'crypto';if(method==='crypto'&&!String(req.body.beneficiaryAddress||'').trim())return res.status(400).json({error:'USDT TRC20 withdrawal wallet is required'});if(method==='bank'&&(!req.body.bankName||!req.body.accountNumber||!req.body.accountName))return res.status(400).json({error:'Complete bank details are required'});const u=db.prepare("SELECT liveness_status,kyc_status,account_status,password_changed_at FROM users WHERE id=?").get(req.user.id);if(u.password_changed_at&&new Date(u.password_changed_at).getTime()+24*3600000>Date.now()){const until=new Date(new Date(u.password_changed_at).getTime()+24*3600000);return res.status(403).json({error:`Withdrawals are disabled for 24 hours after a fundraiser password change. Try again after ${until.toLocaleString()}.`,withdrawalLockedUntil:until.toISOString()});}if(u.account_status==='suspended')return res.status(403).json({error:'Your account is restricted.'});if(u.liveness_status!=='verified')return res.status(400).json({error:'Complete a fresh liveness check before withdrawal'});const r=db.prepare(`INSERT INTO withdrawals(campaign_id,requested_by,amount_usdt,fee_usdt,net_usdt,method,beneficiary_address,bank_name,account_number,account_name,id_file,status,balance_before,balance_after) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(c.id,req.user.id,amount,fee,net,method,String(req.body.beneficiaryAddress||''),String(req.body.bankName||''),String(req.body.accountNumber||''),String(req.body.accountName||''),req.file?.filename||'','pending',balance,Math.max(0,balance-amount));db.prepare("UPDATE campaigns SET withdrawal_disabled_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(c.id);const admin=db.prepare("SELECT id FROM users WHERE role='admin' LIMIT 1").get();if(admin)notify(admin.id,'withdrawal_request','New withdrawal request',`${req.user.name} requested ${net.toFixed(2)} USDT net from ${c.title}.`,{withdrawalId:r.lastInsertRowid});res.status(201).json({ok:true,withdrawalId:r.lastInsertRowid,amount,fee,net,balanceBefore:balance,balanceAfter:Math.max(0,balance-amount),status:'pending'});});
