app.post("/api/beneficiary/received/:id",authRequired,roleRequired("fundraiser"),(req,res)=>{const w=db.prepare("SELECT * FROM withdrawals WHERE id=? AND requested_by=?").get(req.params.id,req.user.id);if(!w)return res.status(404).json({error:'Withdrawal not found'});if(w.status!=='sent')return res.status(400).json({error:'Funds must be marked sent by admin first'});if(w.confirmation_deadline&&new Date(w.confirmation_deadline)<=new Date())return res.status(403).json({error:'The 24-hour confirmation window has expired. Your account is restricted; contact CareFund support.'});db.prepare("UPDATE withdrawals SET status='received',received_at=CURRENT_TIMESTAMP WHERE id=?").run(w.id);db.prepare("UPDATE users SET receipt_deadline=NULL WHERE id=?").run(req.user.id);db.prepare("UPDATE campaigns SET next_campaign_at=? WHERE id=?").run(workdaysFrom(new Date(),7),w.campaign_id);const donors=db.prepare("SELECT DISTINCT donor_user_id FROM donations WHERE campaign_id=? AND status='confirmed' AND donor_user_id IS NOT NULL").all(w.campaign_id);for(const d of donors)notify(d.donor_user_id,'funds_received','Beneficiary confirmed receipt',`The beneficiary has confirmed receipt of ${w.net_usdt.toFixed(2)} USDT for the campaign you supported.`,{campaignId:w.campaign_id,withdrawalId:w.id});notify(req.user.id,'rating_available','Withdrawal completed',`Your funds receipt is confirmed. You can now rate CareFund and leave an appreciation testimony.`);res.json({ok:true,status:'received',ratingAvailable:true,nextCampaignAt:workdaysFrom(new Date(),7)});});
app.get("/api/admin/overview",authRequired,roleRequired("admin"),(req,res)=>{
 const users=db.prepare("SELECT role,COUNT(*) n FROM users GROUP BY role").all();
 const campaigns=db.prepare("SELECT status,COUNT(*) n FROM campaigns GROUP BY status").all();
 const donations=db.prepare("SELECT status,COUNT(*) n,COALESCE(SUM(amount_usdt),0) total FROM donations GROUP BY status").all();
 const withdrawals=db.prepare("SELECT status,COUNT(*) n,COALESCE(SUM(net_usdt),0) total FROM withdrawals GROUP BY status").all();
 const reports=db.prepare("SELECT COUNT(*) n FROM reports WHERE status='open'").get().n;
 const unread=db.prepare("SELECT COUNT(*) n FROM notifications WHERE user_id=? AND read_at IS NULL").get(req.user.id).n;
 res.json({users,campaigns,donations,withdrawals,openReports:reports,unreadNotifications:unread});
});
app.get("/api/admin/users",authRequired,roleRequired("admin"),(req,res)=>{
 const role=String(req.query.role||'').trim();
 const rows=role&&['donor','fundraiser','admin'].includes(role)?db.prepare("SELECT id,name,email,role,country,state,kyc_status,liveness_status,account_status,email_verified,created_at FROM users WHERE role=? ORDER BY id DESC LIMIT 500").all(role):db.prepare("SELECT id,name,email,role,country,state,kyc_status,liveness_status,account_status,email_verified,created_at FROM users ORDER BY id DESC LIMIT 500").all();
 res.json({users:rows});
});
app.patch("/api/admin/users/:id/status",authRequired,roleRequired("admin"),(req,res)=>{
 const id=Number(req.params.id),status=String(req.body.status||'').trim();
 if(!['active','suspended'].includes(status))return res.status(400).json({error:'Invalid account status'});
 const u=db.prepare("SELECT id,role FROM users WHERE id=?").get(id);if(!u)return res.status(404).json({error:'User not found'});
 if(u.role==='admin'&&status==='suspended')return res.status(400).json({error:'Admin accounts cannot be suspended here'});
 db.prepare("UPDATE users SET account_status=? WHERE id=?").run(status,id);notify(id,'account_status','Account status updated',status==='suspended'?'Your CareFund account has been restricted. Contact support for assistance.':'Your CareFund account has been restored.',{});res.json({ok:true,status});
});
app.get("/api/admin/platform-ratings",authRequired,roleRequired("admin"),(req,res)=>res.json({ratings:db.prepare(`SELECT r.*,u.name,u.email,u.role FROM platform_ratings r JOIN users u ON u.id=r.user_id ORDER BY r.updated_at DESC LIMIT 500`).all()}));
app.get("/api/admin/testimonies",authRequired,roleRequired("admin"),(req,res)=>res.json({testimonies:db.prepare(`SELECT t.*,u.name,u.email,u.role FROM testimonies t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 500`).all()}));
app.delete("/api/admin/testimonies/:id",authRequired,roleRequired("admin"),(req,res)=>{db.prepare("DELETE FROM testimonies WHERE id=?").run(req.params.id);res.json({ok:true});});
app.get("/api/admin/messages",authRequired,roleRequired("admin"),(req,res)=>res.json({messages:db.prepare(`SELECT m.*,s.name sender_name,s.email sender_email,c.title campaign_title FROM messages m JOIN users s ON s.id=m.sender_id LEFT JOIN campaigns c ON c.id=m.campaign_id WHERE m.recipient_id=? ORDER BY m.id DESC LIMIT 500`).all(req.user.id)}));
app.get("/api/admin/reports",authRequired,roleRequired("admin"),(req,res)=>res.json({reports:db.prepare(`SELECT r.*,c.title,u.name reporter_name,u.email reporter_email FROM reports r JOIN campaigns c ON c.id=r.campaign_id LEFT JOIN users u ON u.id=r.reporter_user_id WHERE r.status='open' ORDER BY r.id ASC LIMIT 500`).all()}));
app.patch("/api/admin/reports/:id",authRequired,roleRequired("admin"),(req,res)=>{const status=['open','reviewed','resolved','dismissed'].includes(String(req.body.status||''))?String(req.body.status):'reviewed';db.prepare("UPDATE reports SET status=? WHERE id=?").run(status,req.params.id);res.json({ok:true,status});});
app.get("/api/admin/notifications",authRequired,roleRequired("admin"),(req,res)=>res.json({notifications:db.prepare("SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 200").all(req.user.id)}));
app.get("/api/admin/donations/pending",authRequired,roleRequired("admin"),(req,res)=>res.json({donations:db.prepare(`SELECT d.*,c.title,c.patient_name,u.name donor_name,u.email,u.country,u.profile_photo,u.kyc_status FROM donations d JOIN campaigns c ON c.id=d.campaign_id LEFT JOIN users u ON u.id=d.donor_user_id WHERE d.status='pending' ORDER BY d.id ASC`).all()}));
app.post("/api/admin/donations/:id/received",authRequired,roleRequired("admin"),(req,res)=>{const d=db.prepare("SELECT d.*,c.* FROM donations d JOIN campaigns c ON c.id=d.campaign_id WHERE d.id=? AND d.status='pending'").get(req.params.id);if(!d)return res.status(404).json({error:'Pending donation not found'});const remaining=d.goal_usdt-d.raised_usdt;if(d.amount_usdt>remaining+0.000001)return res.status(400).json({error:'Cannot verify this donation because it would exceed the campaign target'});db.prepare("UPDATE donations SET status='confirmed',verified_at=CURRENT_TIMESTAMP WHERE id=?").run(d.id);db.prepare("UPDATE campaigns SET raised_usdt=raised_usdt+?,updated_at=CURRENT_TIMESTAMP,status=CASE WHEN raised_usdt+?>=goal_usdt THEN 'closed' ELSE status END WHERE id=?").run(d.amount_usdt,d.amount_usdt,d.campaign_id);if(d.donor_user_id)notify(d.donor_user_id,'donation_verified','Donation verified',`Your ${d.amount_usdt} USDT donation to ${d.title} has been verified by CareFund.`,{donationId:d.id,campaignId:d.campaign_id});const camp=db.prepare("SELECT * FROM campaigns WHERE id=?").get(d.campaign_id);notify(d.user_id,'donation_received','Donation received',`${d.amount_usdt} USDT from ${d.donor_name||'a donor'} was verified for your campaign.`,{campaignId:d.campaign_id,donationId:d.id});res.json({ok:true,donationId:d.id,campaign:pub(camp)});});
app.post("/api/admin/donations/:id/reject",authRequired,roleRequired("admin"),(req,res)=>{const d=db.prepare("SELECT * FROM donations WHERE id=? AND status='pending'").get(req.params.id);if(!d)return res.status(404).json({error:'Pending donation not found'});db.prepare("UPDATE donations SET status='rejected' WHERE id=?").run(d.id);if(d.donor_user_id)notify(d.donor_user_id,'donation_rejected','Donation not verified','Your payment claim was not verified by CareFund. Please contact support if you believe this is an error.',{donationId:d.id});res.json({ok:true});});
app.get("/api/admin/withdrawals",authRequired,roleRequired("admin"),(req,res)=>res.json({withdrawals:db.prepare(`SELECT w.*,c.title,c.raised_usdt,c.goal_usdt,u.name beneficiary_name,u.email,u.country,u.kyc_status,u.liveness_status FROM withdrawals w JOIN campaigns c ON c.id=w.campaign_id JOIN users u ON u.id=w.requested_by ORDER BY w.id ASC`).all()}));
app.post("/api/admin/withdrawals/:id/approve",authRequired,roleRequired("admin"),(req,res)=>{const w=db.prepare("SELECT * FROM withdrawals WHERE id=? AND status='pending'").get(req.params.id);if(!w)return res.status(404).json({error:'Withdrawal not found'});db.prepare("UPDATE withdrawals SET status='approved' WHERE id=?").run(w.id);notify(w.requested_by,'withdrawal_processing','Withdrawal approved',`Your withdrawal of ${w.net_usdt.toFixed(2)} USDT net has been approved and is being processed.`,{withdrawalId:w.id});res.json({ok:true});});
app.post("/api/admin/withdrawals/:id/reject",authRequired,roleRequired("admin"),(req,res)=>{const w=db.prepare("SELECT * FROM withdrawals WHERE id=? AND status IN ('pending','approved','processing')").get(req.params.id);if(!w)return res.status(404).json({error:'Withdrawal is not available for rejection'});const note=String(req.body.note||'Withdrawal request was not approved. Please contact CareFund support.').trim().slice(0,500);db.prepare("UPDATE withdrawals SET status='rejected',admin_note=? WHERE id=?").run(note,w.id);db.prepare("UPDATE campaigns SET withdrawal_disabled_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(w.campaign_id);notify(w.requested_by,'withdrawal_rejected','Withdrawal request declined',note,{withdrawalId:w.id,campaignId:w.campaign_id});res.json({ok:true,status:'rejected'});});
app.post("/api/admin/withdrawals/:id/sent",authRequired,roleRequired("admin"),(req,res)=>{const w=db.prepare("SELECT * FROM withdrawals WHERE id=? AND status IN ('approved','processing')").get(req.params.id);if(!w)return res.status(404).json({error:'Withdrawal is not ready to mark sent'});const tx=normalizeTxid(req.body.txHash),ref=String(req.body.reference||'').trim();if(w.method==='crypto'&&!txidRegex.test(tx))return res.status(400).json({error:"A valid 64-character payout TXID is required for crypto withdrawals"});db.prepare("UPDATE withdrawals SET status='sent',payout_tx_hash=?,transfer_reference=?,sent_at=CURRENT_TIMESTAMP,confirmation_started_at=NULL,confirmation_deadline=NULL,confirmation_notified_at=NULL WHERE id=?").run(tx,ref,w.id);db.prepare("UPDATE users SET receipt_deadline=NULL WHERE id=?").run(w.requested_by);notify(w.requested_by,'funds_sent','🔔 FUNDS SENT — CONFIRM RECEIPT',`CareFund has sent your withdrawal. When you next log in, a 24-hour confirmation window will start.`,{withdrawalId:w.id,netUsdt:w.net_usdt});const donors=db.prepare("SELECT DISTINCT donor_user_id FROM donations WHERE campaign_id=? AND status='confirmed' AND donor_user_id IS NOT NULL").all(w.campaign_id);for(const d of donors)notify(d.donor_user_id,'beneficiary_paid','Campaign funds sent',`Campaign funds have been sent to the beneficiary.`,{campaignId:w.campaign_id,withdrawalId:w.id});res.json({ok:true,status:'sent',netUsdt:w.net_usdt,confirmationStartsOnNextLogin:true});});
app.get("/api/admin/campaigns/:id/evidence",authRequired,roleRequired("admin"),(req,res)=>{const c=db.prepare("SELECT * FROM campaigns WHERE id=?").get(req.params.id);if(!c)return res.status(404).json({error:'Campaign not found'});res.json({campaign:campaignEvidence(c)});});
app.get("/api/admin/campaign-files/:fileId",authRequired,roleRequired("admin"),(req,res)=>{const f=db.prepare("SELECT * FROM campaign_files WHERE id=?").get(req.params.fileId);if(!f)return res.status(404).end();res.sendFile(path.join(uploadDir,f.stored_name),{headers:{'Content-Disposition':`inline; filename=\"${String(f.file_name).replace(/\"/g,'')}\"`}});});
app.get("/api/admin/liveness/:userId",authRequired,roleRequired("admin"),(req,res)=>{const u=db.prepare("SELECT liveness_file FROM users WHERE id=?").get(req.params.userId);if(!u?.liveness_file)return res.status(404).end();res.sendFile(path.join(uploadDir,u.liveness_file));});
app.post("/api/admin/campaigns/:id/verify",authRequired,roleRequired("admin"),(req,res)=>{const c=db.prepare("SELECT * FROM campaigns WHERE id=?").get(req.params.id);if(!c)return res.status(404).json({error:'Campaign not found'});const decision=req.body.decision==='approve'?'approve':req.body.decision==='reject'?'reject':'request_more';const note=String(req.body.note||'').trim();if(decision==='approve'){const medicalDocs=db.prepare("SELECT COUNT(*) n FROM campaign_files WHERE campaign_id=? AND kind='document'").get(c.id).n;const identityDocs=db.prepare("SELECT COUNT(*) n FROM campaign_files WHERE campaign_id=? AND kind='identity'").get(c.id).n;if(c.creator_liveness_status!=='verified'||medicalDocs<1||identityDocs<1)return res.status(400).json({error:'Approve only after liveness, government ID and at least one medical/supporting document are present'});db.prepare("UPDATE campaigns SET status='approved',verified=1,verification_status='verified',verification_notes=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(note,req.user.id,c.id);db.prepare("UPDATE users SET kyc_status='verified' WHERE id=?").run(c.user_id);notify(c.user_id,'campaign_approved','Campaign verified and approved',`Your campaign “${c.title}” passed CareFund review and is now live.`,{campaignId:c.id});return res.json({ok:true,status:'approved'});}if(decision==='reject'){db.prepare("UPDATE campaigns SET status='rejected',verified=0,verification_status='rejected',verification_notes=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(note,req.user.id,c.id);notify(c.user_id,'campaign_rejected','Campaign verification declined',note||'Your campaign was not approved. Please contact CareFund support.',{campaignId:c.id});return res.json({ok:true,status:'rejected'});}db.prepare("UPDATE campaigns SET status='pending',verified=0,verification_status='more_evidence',verification_notes=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(note,req.user.id,c.id);notify(c.user_id,'campaign_more_evidence','More evidence required',note||'CareFund needs additional evidence before your campaign can be approved.',{campaignId:c.id});res.json({ok:true,status:'more_evidence'});});
app.post("/api/admin/campaigns/:id/approve",authRequired,roleRequired("admin"),(req,res)=>{req.body={decision:'approve',note:req.body?.note||''};const c=db.prepare("SELECT * FROM campaigns WHERE id=?").get(req.params.id);if(!c)return res.status(404).json({error:'Campaign not found'});const medicalDocs=db.prepare("SELECT COUNT(*) n FROM campaign_files WHERE campaign_id=? AND kind='document'").get(c.id).n;const identityDocs=db.prepare("SELECT COUNT(*) n FROM campaign_files WHERE campaign_id=? AND kind='identity'").get(c.id).n;if(c.creator_liveness_status!=='verified'||medicalDocs<1||identityDocs<1)return res.status(400).json({error:'Liveness, government ID and supporting medical evidence are required before approval'});db.prepare("UPDATE campaigns SET status='approved',verified=1,verification_status='verified',verification_notes=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body.note,req.user.id,c.id);db.prepare("UPDATE users SET kyc_status='verified' WHERE id=?").run(c.user_id);notify(c.user_id,'campaign_approved','Campaign verified and approved',`Your campaign “${c.title}” is now live on CareFund.`,{campaignId:c.id});res.json({ok:true});});
app.post("/api/admin/campaigns/:id/reject",authRequired,roleRequired("admin"),(req,res)=>{const c=db.prepare("SELECT * FROM campaigns WHERE id=?").get(req.params.id);if(!c)return res.status(404).json({error:'Campaign not found'});db.prepare("UPDATE campaigns SET status='rejected',verified=0,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(c.id);notify(c.user_id,'campaign_rejected','Campaign needs changes',String(req.body.note||'Your campaign was not approved. Please contact support.'),{campaignId:c.id});res.json({ok:true});});
app.get("/api/admin/campaigns",authRequired,roleRequired("admin"),(req,res)=>{const status=String(req.query.status||'pending');res.json({campaigns:db.prepare("SELECT * FROM campaigns WHERE status=? ORDER BY created_at ASC").all(status).map(pub)});});
app.post("/api/messages",authRequired,(req,res)=>{const body=String(req.body.body||'').trim();let recipient=Number(req.body.recipientId);if(!body)return res.status(400).json({error:'Message required'});if(req.user.role!=='admin')recipient=db.prepare("SELECT id FROM users WHERE role='admin' LIMIT 1").get()?.id;if(!recipient)return res.status(404).json({error:'Admin not configured'});const r=db.prepare("INSERT INTO messages(sender_id,recipient_id,campaign_id,body) VALUES(?,?,?,?)").run(req.user.id,recipient,req.body.campaignId||null,body);notify(recipient,'message','New support message',`${req.user.name}: ${body}`,{messageId:r.lastInsertRowid});res.status(201).json({ok:true});});
app.get("/api/messages",authRequired,(req,res)=>res.json({messages:db.prepare(`SELECT m.*,s.name sender_name,r.name recipient_name FROM messages m JOIN users s ON s.id=m.sender_id JOIN users r ON r.id=m.recipient_id WHERE m.sender_id=? OR m.recipient_id=? ORDER BY m.id ASC`).all(req.user.id,req.user.id)}));
app.get("/api/public/donors",(req,res)=>{const rows=db.prepare(`SELECT id,name,country,profile_photo,donor_rating FROM users WHERE role='donor' ORDER BY CASE WHEN donor_rating>0 THEN 0 ELSE 1 END, donor_rating DESC, name ASC`).all();res.json({donors:rows.map(x=>({...x,level:donorLevel(x.id),countryName:x.country||'Unknown'}))});});
app.get("/api/inspiration",authRequired,roleRequired("donor"),(req,res)=>{const u=db.prepare("SELECT inspiration_last_shown FROM users WHERE id=?").get(req.user.id);const now=Date.now();const last=u?.inspiration_last_shown?new Date(u.inspiration_last_shown).getTime():0;if(now-last<24*3600000)return res.json({show:false,nextAt:new Date(last+24*3600000).toISOString()});db.prepare("UPDATE users SET inspiration_last_shown=CURRENT_TIMESTAMP WHERE id=?").run(req.user.id);res.json({show:true,title:'Your kindness can change a life',message:'A small donation can help someone reach urgent care, treatment or recovery.',nextAt:new Date(now+24*3600000).toISOString()});});
app.get("/api/testimonies",(req,res)=>{const rows=db.prepare(`SELECT t.rating,t.message,t.created_at,u.name,u.country,u.profile_photo FROM testimonies t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 100`).all();res.json({testimonies:rows.map(x=>({...x,verified:true,countryName:x.country||'Unknown'}))});});
app.post("/api/testimonies",authRequired,roleRequired("fundraiser"),(req,res)=>{const rating=Number(req.body.rating),message=cleanTestimony(req.body.message);const eligible=db.prepare("SELECT id FROM withdrawals WHERE requested_by=? AND status='received' LIMIT 1").get(req.user.id);if(!eligible)return res.status(403).json({error:'Testimony is available after a completed withdrawal and receipt confirmation.'});if(!Number.isInteger(rating)||rating<1||rating>5)return res.status(400).json({error:'Choose a rating from 1 to 5.'});if(!message)return res.status(400).json({error:'Appreciation message is required.'});if(containsPrivateData(message))return res.status(400).json({error:'Do not include email addresses, phone numbers, wallet addresses, bank/card details, URLs or social contact information.'});db.prepare(`INSERT INTO testimonies(user_id,rating,message) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET rating=excluded.rating,message=excluded.message,created_at=CURRENT_TIMESTAMP`).run(req.user.id,rating,message);res.json({ok:true});});
app.get("/api/health-information",(req,res)=>res.json({articles:db.prepare("SELECT id,title,intro,content,image_file,updated_at FROM health_articles WHERE published=1 ORDER BY id DESC").all()}));
app.get("/api/health-information/:id",(req,res)=>{const a=db.prepare("SELECT id,title,intro,content,image_file,updated_at FROM health_articles WHERE id=? AND published=1").get(req.params.id);if(!a)return res.status(404).json({error:'Health article not found'});res.json({article:a});});
app.get("/api/admin/health-information",authRequired,roleRequired("admin"),(req,res)=>res.json({articles:db.prepare("SELECT * FROM health_articles ORDER BY id DESC").all()}));
app.post("/api/admin/health-information",authRequired,roleRequired("admin"),(req,res)=>{const title=String(req.body.title||'').trim(),intro=String(req.body.intro||'').trim(),content=String(req.body.content||'').trim();if(!title||!intro||!content)return res.status(400).json({error:'Title, intro and content are required'});const r=db.prepare("INSERT INTO health_articles(title,intro,content,image_file,published) VALUES(?,?,?,?,?)").run(title,intro,content,String(req.body.imageFile||''),req.body.published?1:0);res.status(201).json({ok:true,id:r.lastInsertRowid});});
app.patch("/api/admin/health-information/:id",authRequired,roleRequired("admin"),(req,res)=>{const a=db.prepare("SELECT * FROM health_articles WHERE id=?").get(req.params.id);if(!a)return res.status(404).json({error:'Article not found'});db.prepare("UPDATE health_articles SET title=?,intro=?,content=?,image_file=?,published=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(String(req.body.title??a.title),String(req.body.intro??a.intro),String(req.body.content??a.content),String(req.body.imageFile??a.image_file),req.body.published===undefined?a.published:(req.body.published?1:0),a.id);res.json({ok:true});});
app.delete("/api/admin/health-information/:id",authRequired,roleRequired("admin"),(req,res)=>{db.prepare("DELETE FROM health_articles WHERE id=?").run(req.params.id);res.json({ok:true});});
app.use(express.static(__dirname));
app.get('/',(req,res)=>res.sendFile(path.join(__dirname,'index.html')));
app.use((err,req,res,next)=>{if(err instanceof multer.MulterError)return res.status(400).json({error:err.message});if(err)return res.status(400).json({error:err.message||'Request failed'});next();});
app.listen(PORT,()=>console.log(`CareFund backend running at http://localhost:${PORT}`));
